package vn.luma.web;

import java.math.BigDecimal;
import java.security.Principal;
import java.util.*;
import jakarta.validation.Valid;
import org.springframework.stereotype.Controller;
import org.springframework.ui.Model;
import org.springframework.validation.BindingResult;
import org.springframework.web.bind.annotation.*;
import org.springframework.web.servlet.mvc.support.RedirectAttributes;
import vn.luma.business.QuanLySanPhamService;

@Controller
@RequestMapping("/quan-tri")
public class QuanLySanPhamController {
    private final vn.luma.business.CauHinhSanPhamService configuration;private final QuanLySanPhamService service;
    public QuanLySanPhamController(QuanLySanPhamService service,vn.luma.business.CauHinhSanPhamService configuration){this.service=service;this.configuration=configuration;}
    @GetMapping("/model") public String danhSach(@RequestParam(defaultValue="") String q,@RequestParam(defaultValue="1") int trang,Principal user,Model model){model.addAttribute("trang",trang);model.addAttribute("modelSanPham",service.danhSach(user.getName(),q,trang));model.addAttribute("q",q);return "quan-tri/model";}
    private void chonDanhMuc(Principal user,Model model){model.addAttribute("danhMuc",service.danhMuc(user.getName(),"phan-loai"));model.addAttribute("thuongHieu",service.danhMuc(user.getName(),"thuong-hieu"));}
    @GetMapping("/model/moi") public String moi(Principal user,Model model){chonDanhMuc(user,model);model.addAttribute("maModel",null);if(!model.containsAttribute("form"))model.addAttribute("form",new NoiDungSanPhamYeuCau(0,0,"","","","",12,"",false));return "quan-tri/model-form";}
    @GetMapping("/model/{id}") public String sua(@PathVariable long id,Principal user,Model model){var row=service.model(user.getName(),id);chonDanhMuc(user,model);model.addAttribute("maModel",id);model.addAttribute("modelSp",row);model.addAttribute("dongSanPham",configuration.dongCuaModel(user.getName(),id));model.addAttribute("sku",service.bienThe(user.getName(),id));if(!model.containsAttribute("form"))model.addAttribute("form",new NoiDungSanPhamYeuCau(number(row,"MaPhanLoai"),number(row,"MaThuongHieu"),(String)row.get("TenSanPham"),(String)row.get("DuongDan"),(String)row.get("MoTaNgan"),(String)row.get("MoTaChiTiet"),((Number)row.get("SoThangBaoHanh")).intValue(),(String)row.get("DuongDanNguon"),(Boolean)row.get("DangHienThi")));return "quan-tri/model-form";}
    @PostMapping({"/model/moi","/model/{id}"}) public String luu(@PathVariable(required=false) Long id,@Valid @ModelAttribute("form") NoiDungSanPhamYeuCau form,BindingResult errors,Principal user,Model model,RedirectAttributes flash){if(!errors.hasErrors())try{long saved=service.luuModel(user.getName(),id,form);flash.addFlashAttribute("thongBao","Đã lưu nội dung model.");return "redirect:/quan-tri/model/"+saved;}catch(IllegalArgumentException ex){model.addAttribute("loi",ex.getMessage());}return id==null?moi(user,model):sua(id,user,model);}
    @PostMapping("/model/{id}/an") public String an(@PathVariable long id,Principal user,RedirectAttributes flash){service.anModel(user.getName(),id);flash.addFlashAttribute("thongBao","Đã ẩn model. Lịch sử đơn giữ theo bản chụp gốc.");return "redirect:/quan-tri/model";}
    @GetMapping("/model/{product}/sku/moi") public String moiSku(@PathVariable long product,Principal user,Model model){model.addAttribute("modelSp",service.model(user.getName(),product));model.addAttribute("maSku",null);if(!model.containsAttribute("form"))model.addAttribute("form",new NoiDungBienTheYeuCau("","","","","","",8,256,null,"",false,new CapNhatBienThe(null,null,null,0,"")));return "quan-tri/sku-form";}
    @GetMapping("/model/{product}/sku/{sku}") public String suaSku(@PathVariable long product,@PathVariable long sku,Principal user,Model model){model.addAttribute("modelSp",service.model(user.getName(),product));var row=service.bienThe(user.getName(),product).stream().filter(v->number(v,"MaBienThe")==sku).findFirst().orElseThrow(()->new vn.luma.business.KhongTimThayException("SKU không thuộc model này."));model.addAttribute("maSku",sku);if(!model.containsAttribute("form"))model.addAttribute("form",new NoiDungBienTheYeuCau((String)row.get("MaHang"),(String)row.get("MaMayHang"),(String)row.get("TenBienThe"),(String)row.get("MauSac"),(String)row.get("BoXuLy"),(String)row.get("BoXuLyDoHoa"),((Number)row.get("DungLuongRam")).intValue(),((Number)row.get("DungLuongLuuTru")).intValue(),(BigDecimal)row.get("KichThuocManHinh"),(String)row.get("HeDieuHanh"),(Boolean)row.get("DangKinhDoanh"),new CapNhatBienThe((BigDecimal)row.get("GiaBan"),(BigDecimal)row.get("GiaNiemYet"),(BigDecimal)row.get("GiaVon"),((Number)row.get("TonVatLy")).intValue(),"")));return "quan-tri/sku-form";}
    @PostMapping({"/model/{product}/sku/moi","/model/{product}/sku/{sku}"}) public String luuSku(@PathVariable long product,@PathVariable(required=false) Long sku,@Valid @ModelAttribute("form") NoiDungBienTheYeuCau form,BindingResult errors,Principal user,Model model,RedirectAttributes flash){if(!errors.hasErrors())try{service.luuSku(user.getName(),product,sku,form);flash.addFlashAttribute("thongBao","Đã lưu SKU, lịch sử giá và sổ kho.");return "redirect:/quan-tri/model/"+product;}catch(IllegalArgumentException ex){model.addAttribute("loi",ex.getMessage());}return sku==null?moiSku(product,user,model):suaSku(product,sku,user,model);}
    @PostMapping("/sku/{sku}/ngung") public String ngung(@PathVariable long sku,Principal user,RedirectAttributes flash){var row=service.sku(user.getName(),sku);service.ngungSku(user.getName(),sku);flash.addFlashAttribute("thongBao","Đã ngừng bán SKU. Các đơn đã chốt được giữ nguyên.");return "redirect:/quan-tri/model/"+number(row,"MaSanPham");}
    @GetMapping("/danh-muc/{type}") public String danhMuc(@PathVariable String type,Principal user,Model model){service.loai(type);model.addAttribute("loai",type);model.addAttribute("muc",service.danhMuc(user.getName(),type));return "quan-tri/danh-muc";}
    @GetMapping("/danh-muc/{type}/moi") public String mucMoi(@PathVariable String type,Principal user,Model model){service.danhMuc(user.getName(),type);model.addAttribute("loai",type);model.addAttribute("maMuc",null);if(!model.containsAttribute("form"))model.addAttribute("form",new MucDanhMucYeuCau("","","",0,false));return "quan-tri/danh-muc-form";}
    @GetMapping("/danh-muc/{type}/{id}") public String mucSua(@PathVariable String type,@PathVariable long id,Principal user,Model model){var row=service.muc(user.getName(),type,id);model.addAttribute("loai",type);model.addAttribute("maMuc",id);if(!model.containsAttribute("form"))model.addAttribute("form",new MucDanhMucYeuCau((String)row.get("Ten"),(String)row.get("DuongDan"),(String)row.get("MoTa"),((Number)row.get("ThuTu")).intValue(),(Boolean)row.get("DangHienThi")));return "quan-tri/danh-muc-form";}
    @PostMapping({"/danh-muc/{type}/moi","/danh-muc/{type}/{id}"}) public String mucLuu(@PathVariable String type,@PathVariable(required=false) Long id,@Valid @ModelAttribute("form") MucDanhMucYeuCau form,BindingResult errors,Principal user,Model model,RedirectAttributes flash){if(!errors.hasErrors())try{service.luuMuc(user.getName(),type,id,form);flash.addFlashAttribute("thongBao","Đã lưu danh mục.");return "redirect:/quan-tri/danh-muc/"+type;}catch(IllegalArgumentException ex){model.addAttribute("loi",ex.getMessage());}return id==null?mucMoi(type,user,model):mucSua(type,id,user,model);}
    @PostMapping("/danh-muc/{type}/{id}/an") public String mucAn(@PathVariable String type,@PathVariable long id,Principal user,RedirectAttributes flash){service.anMuc(user.getName(),type,id);flash.addFlashAttribute("thongBao","Đã ẩn mục danh mục. Các bản chụp đơn giữ nguyên.");return "redirect:/quan-tri/danh-muc/"+type;}
    private long number(Map<String,Object> row,String key){return ((Number)row.get(key)).longValue();}
}
